package dev.openallay.runtime.forge1122;
public final class FarmerHolderTest {
    public static void main(String[] args) throws Exception {
        System.setProperty("openallay.objectholder.fields",args[0]);System.setProperty("openallay.objectholder.metadata",args[1]);
        byte[] raw=java.util.Base64.getDecoder().decode("");
        byte[] patched=ObjectHolderBridge.patchFarmer(raw);
        if(!ObjectHolderBridge.methodInstructions(raw).equals(ObjectHolderBridge.methodInstructions(patched)))throw new AssertionError("Farmer init methods changed");
        org.objectweb.asm.tree.ClassNode a=new org.objectweb.asm.tree.ClassNode(),b=new org.objectweb.asm.tree.ClassNode();
        new org.objectweb.asm.ClassReader(raw).accept(a,0);new org.objectweb.asm.ClassReader(patched).accept(b,0);
        for(int i=0;i<a.fields.size();i++) {
            org.objectweb.asm.tree.FieldNode x=(org.objectweb.asm.tree.FieldNode)a.fields.get(i),y=(org.objectweb.asm.tree.FieldNode)b.fields.get(i);
            if("FARMER".equals(x.name)){if(x.access!=25||y.access!=9)throw new AssertionError("Exact farmer flags");}
            else if(x.access!=y.access)throw new AssertionError("Foreign field flags changed");
        }
        System.out.println("PASS real official farmer @ObjectHolder only; foreign field flags and all initialization instructions unchanged");
    }
}
